int **multiSearch(char *big, char **smalls, int smallsSize, int *returnSize, int **returnColumnSizes) {
  int bl = strlen(big);
  int **res = (int **)malloc(sizeof(int *) * smallsSize);
  *returnColumnSizes = (int *)malloc(sizeof(int) * smallsSize);
  *returnSize = smallsSize;
  for (int i = 0; i < smallsSize; i++) {
    int sl = strlen(smalls[i]);
    int *pos = (int *)malloc(sizeof(int) * (bl + 1));
    int count = 0;
    if (sl > 0) {
      for (int j = 0; j + sl <= bl; j++) {
        if (strncmp(big + j, smalls[i], sl) == 0) pos[count++] = j;
      }
    }
    res[i] = pos;
    (*returnColumnSizes)[i] = count;
  }
  return res;
}

class Solution {
public:
  vector<vector<int>> multiSearch(string big, vector<string> &smalls) {
    vector<vector<int>> res;
    int bl = big.size();
    for (const string &s : smalls) {
      vector<int> pos;
      int sl = s.size();
      if (sl > 0) {
        for (int j = 0; j + sl <= bl; j++) {
          if (big.compare(j, sl, s) == 0) pos.push_back(j);
        }
      }
      res.push_back(pos);
    }
    return res;
  }
};

func multiSearch(big string, smalls []string) [][]int {
	res := [][]int{}
	for _, s := range smalls {
		pos := []int{}
		if len(s) > 0 {
			for j := 0; j+len(s) <= len(big); j++ {
				if big[j:j+len(s)] == s {
					pos = append(pos, j)
				}
			}
		}
		res = append(res, pos)
	}
	return res
}

class Solution {
  public int[][] multiSearch(String big, String[] smalls) {
    int[][] res = new int[smalls.length][];
    for (int i = 0; i < smalls.length; i++) {
      List<Integer> pos = new ArrayList<>();
      String s = smalls[i];
      if (s.length() > 0) {
        for (int j = 0; j + s.length() <= big.length(); j++) {
          if (big.startsWith(s, j)) pos.add(j);
        }
      }
      res[i] = pos.stream().mapToInt(Integer::intValue).toArray();
    }
    return res;
  }
}

class Solution:
    def multiSearch(self, big: str, smalls: List[str]) -> List[List[int]]:
        res = []
        for s in smalls:
            pos = []
            if s:
                start = 0
                while True:
                    idx = big.find(s, start)
                    if idx == -1:
                        break
                    pos.append(idx)
                    start = idx + 1
            res.append(pos)
        return res

impl Solution {
  pub fn multi_search(big: String, smalls: Vec<String>) -> Vec<Vec<i32>> {
    let mut res = vec![];
    let b = big.as_bytes();
    for s in smalls {
      let mut pos = vec![];
      let sb = s.as_bytes();
      if !sb.is_empty() {
        for j in 0..=b.len().saturating_sub(sb.len()) {
          if &b[j..j + sb.len()] == sb {
            pos.push(j as i32);
          }
        }
      }
      res.push(pos);
    }
    res
  }
}

const multiSearch = (big: string, smalls: string[]): number[][] => {
  const res: number[][] = [];
  for (const s of smalls) {
    const pos: number[] = [];
    if (s.length > 0) {
      let start = 0;
      while (true) {
        const idx = big.indexOf(s, start);
        if (idx === -1) break;
        pos.push(idx);
        start = idx + 1;
      }
    }
    res.push(pos);
  }
  return res;
};
